/** Parse actual SVG text and geometry against fixed source roles; never execute SVG. */
import assert from'node:assert/strict';import facts from'./legacy-2019-pm-ranking-facts.json';
const decode=(s:string)=>s.replace(/<[^>]*>/g,'').replaceAll('&amp;','&').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&quot;','"').replaceAll('&#x27;',"'");const attrs=(s:string)=>Object.fromEntries([...s.matchAll(/([\w:-]+)="([^"]*)"/g)].map(m=>[m[1],decode(m[2])]));
export function readLegacy2019RankingFigure(svg:string,profile:string,policy:number){const k=facts.profiles.indexOf(profile);assert(k>=0);const tags:({value:string}&Record<string,string>)[]=[...svg.matchAll(/<text\b([^>]*)>([\s\S]*?)<\/text>/g)].map(m=>({...attrs(m[1]),value:decode(m[2])}));const one=(key:string)=>{const rows=tags.filter(t=>t['data-ranking-text']===key);assert.equal(rows.length,1,key);return rows[0];},text=(key:string,value:string)=>{const t=one(key);assert.equal(t.value,value);return t;},rects=[...svg.matchAll(/<rect\b([^>]*)>/g)].map(m=>attrs(m[1])),frame=rects.filter(r=>'data-ranking-frame'in r);assert.equal(frame.length,1);assert.deepEqual([+frame[0].x,+frame[0].y,+frame[0].width,+frame[0].height],[[20,20,1080,170],[20,20,1060,210],[20,20,1060,320],[20,20,1120,130],[20,20,1320,990]][k]);const checkCell=(key:string,value:string,x:number,y:number)=>{const t=text(key,value);assert.deepEqual([+t.x,+t.y],[x,y]);assert(+t.x>+frame[0].x&&+t.x<+frame[0].x + +frame[0].width);assert(+t.y>+frame[0].y&&+t.y<+frame[0].y + +frame[0].height);};
 if(k===0){checkCell('student','塾生番号',110,85);checkCell('student-digits','6桁',110,130);checkCell('school','校舎番号',275,85);checkCell('school-digits','2桁',275,130);checkCell('group','テスト結果',725,55);for(let i=0;i<5;i++){checkCell('subject-'+i,['国語','数学','英語','理科','社会'][i],425+i*150,120);checkCell('digits-'+i,'3桁',425+i*150,160);}const lines=[...svg.matchAll(/<line\b([^>]*)>/g)].map(m=>attrs(m[1]));assert.equal(lines.length,7);for(let i=0;i<6;i++){const t=lines.find(l=>l['data-ranking-separator']===String([200,350,500,650,800,950][i]));assert(t);assert.equal(+t.y1,i<2?20:80);assert.equal(+t.y2,190);}const span=lines.find(l=>l['data-ranking-span']==='subjects')!;assert.deepEqual([+span.x1,+span.x2,+span.y1,+span.y2],[350,1100,80,80]);}
 else if(k===1||k===2){const xs=[125,335,545,755,965],headers=['全体順位','塾生番号','校舎番号','校舎内順位',policy?'合計失点':'合計点'];headers.forEach((v,i)=>checkCell('header-'+i,v,xs[i],55));const totals=policy?[8,12,12,13]:[492,488,488,487],rows=k===1?[['ZZ9','999999','99','ZZ9','ZZ9'],['ZZ9','999999','99','ZZ9','ZZ9']]:[[1,'182025','02',1,totals[0]],[2,'181007','01',1,totals[1]],[2,'182038','02',2,totals[2]],[4,'185011','05',1,totals[3]]];rows.forEach((r,i)=>r.forEach((v,j)=>checkCell('cell-'+i+'-'+j,String(v),xs[j],105+i*45)));xs.forEach((x,i)=>checkCell('ellipsis-'+i,'⋮',x,105+rows.length*45));}
 else if(k===3){checkCell('avg-label','AVG:',40,65);checkCell('avg-picture','ZZ9.9',220,65);checkCell('school-avg-label','BLD-AVG:',40,115);for(let i=0;i<5;i++)checkCell('school-avg-picture-'+i,'ZZ9.9',220+i*175,115);}
 else{checkCell('table-header-left','処置',155,60);checkCell('table-header-right','変更内容',815,60);const lines=[...svg.matchAll(/<line\b([^>]*)>/g)].map(m=>attrs(m[1]));assert.equal(lines.length,5);const div=lines.find(l=>l['data-ranking-table']==='column')!;assert.deepEqual([+div.x1,+div.y1,+div.x2,+div.y2],[290,20,290,1010]);for(let i=0;i<4;i++){const row=lines.find(l=>l['data-ranking-table']==='row-'+i)!;assert.deepEqual([+row.x1,+row.x2,+row.y1,+row.y2],[20,1340,[85,275,400,905][i],[85,275,400,905][i]]);}[['行番号31と32の間','に追加'],['行番号35と36の間','に追加'],['行番号43と44の間','に追加'],['［e］','に追加']].forEach((row,i)=>row.forEach((v,j)=>checkCell('table-left-'+i+'-'+j,v,40,[85,275,400,905][i]+42+j*38)));facts.table.rows.forEach((r,i)=>r.right.forEach((v,j)=>{const t=text('table-right-'+i+'-'+j,v.trim()==='[f]'?'f':v);assert(+t.x>290&&+t.x<1340);assert(+t.y>[85,275,400,905][i]&&+t.y<[275,400,905,1010][i]);}));for(const key of['e','f']){const b=rects.filter(r=>r['data-ranking-blank']===key);assert.equal(b.length,1);assert(+b[0].width>100&&+b[0].height>=38);}}
 const desc=decode(svg.match(/<desc\b[^>]*>([\s\S]*?)<\/desc>/)![1]);assert(desc.length>30);assert.equal(new Set(tags.map(t=>t['data-ranking-text'])).size,tags.length);assert(!/正答|正解/.test(desc));return{texts:tags.length,frame:frame[0],geometry:'pass',profile,policy};}
